memberdef.initializer:
                                        = []() {
    std::string text = {};
    text.reserve(kLegalSentences.size() * 120);
    for (int i = 0; i < 10; ++i) {
        for (const auto& s : kLegalSentences) {
            text += s;
            text += " ";
        }
    }
    return text;
}()
